import com.learningspace.LocalLibrary;import com.learningspace.LanAddress;import java.io.*;import java.nio.file.*;import org.json.*;
public class LocalLibraryCheck {
 public static void main(String[] args)throws Exception{File dir=Files.createTempDirectory("learning-phone-test").toFile(),file=new File(dir,"library.json");LocalLibrary store=new LocalLibrary(file);if(!store.read().isEmpty())throw new AssertionError("Not empty");JSONObject state=new JSONObject().put("version",1).put("resources",new JSONArray()).put("goals",new JSONArray());String input=new JSONObject().put("state",state).put("revision",0).toString();if(new JSONObject(store.save(input)).getInt("revision")!=1)throw new AssertionError();if(new JSONObject(new LocalLibrary(file).read()).getInt("revision")!=1)throw new AssertionError("Restart lost library");if(new JSONObject(store.save(input)).getInt("status")!=409)throw new AssertionError("Stale write accepted");if(!LanAddress.validate("http://192.168.1.20:5180").equals("http://192.168.1.20:5180"))throw new AssertionError();for(String bad:new String[]{"https://example.com","http://8.8.8.8","http://172.32.0.1","http://user:pass@192.168.1.1","file:///tmp/x","http://192.168.1.1/path"}){boolean rejected=false;try{LanAddress.validate(bad);}catch(Exception e){rejected=true;}if(!rejected)throw new AssertionError("Unsafe LAN destination accepted");}file.delete();dir.delete();System.out.println("Native local library checks passed: persistence, restart, stale-write rejection, and private LAN destinations.");}
}
